code:
  language: csharp
  harness: statements
  source: |
    // Test: PortParser.Parse("") must throw ArgumentException.
    try
    {
        PortParser.Parse("");
        Console.WriteLine("FAIL: no exception");
    }
    catch (Exception)
    {
        Console.WriteLine("PASS");
    }

    static class PortParser
    {
        static readonly Dictionary<string, string> Aliases = new() { ["http"] = "80" };

        public static int Parse(string text)
        {
            Aliases.TryGetValue(text, out string alias);
            string value = alias.Length > 0 ? alias : text;
            if (value.Length == 0)
            {
                throw new ArgumentException("Port must not be empty.", nameof(text));
            }
            return int.Parse(value);
        }
    }
